 trials=[('left side high','lower right','higher left','the lower right'),('right side high','lower left','higher right','the lower left'),('paper towel and plastic lid','towel','lid','the towel absorbed the drop; the lid did not'),('cotton cloth and glass tile','cloth','tile','the cloth absorbed the drop; the tile did not'),('sponge and metal tray','sponge','tray','the sponge absorbed the drop; the tray did not'),('hollow block and solid stone','hollow block','stone','the hollow block floated; the stone sank'),('rough ramp and smooth ramp','rough ramp','smooth ramp','the ball stopped sooner on the rough ramp'),('shade and sun puddles','sun puddle','shade puddle','both shrank; the sun puddle shrank more'),('warm and cool wet cloths','warm cloth','cool cloth','the warm cloth dried sooner'),('covered and open cups','open cup','covered cup','the open cup lost more visible water'),('steel clip and wood block','steel clip','wood block','the tested magnet attracted the steel clip only'),('paper sheet and folded paper','folded paper','flat sheet','the folded paper supported the toy; the flat sheet bent')]
 def predict(p,opts,obs,follow,answers,explain):return S(dict(Q(p,opts),mode='predict',observation=obs),Q('Observed record: '+obs+' '+follow,answers,explain=explain,cue='Use the supplied observation.'))
 replace('science',3,0,[predict('Setup: '+setup+'. Which result might occur?',[a,b],'In this supplied trial, '+result+'.','Which report fits this trial?',[result,'Both tested objects always behave identically','This proves a rule for every object'],'Report this trial without extending it to untested objects.') for setup,a,b,result in trials])
 measures=[('leaf count',2,4,2,2),('height marks',3,5,3,3),('open flower count',0,2,0,0),('wet area marks',8,4,8,8),('distance marks',2,6,2,2),('visible holes',1,3,1,1),('water level marks',7,5,7,7),('root length marks',1,4,1,1),('seed count visible',3,5,3,3),('fold count',0,2,0,0),('shadow length marks',4,7,4,4),('dry patches',1,3,1,1)]
 replace('science',3,1,[Q('Record of '+kind+': A first '+str(a)+', later '+str(b)+'. B first '+str(c)+', later '+str(d)+'. Which object changed?',['A changed; B stayed at the recorded value','B changed; A stayed the same','Both stayed the same'],explain='Compare each object’s first and later recorded values.') for kind,a,b,c,d in measures])
 replace('science',3,2,[Q('Supplied record: '+kind+' first '+str(a)+', later '+str(b)+'. What changed?',['The recorded value '+('increased' if b>a else 'decreased'),'The value stayed the same','The record establishes the reason for the change'],explain='The record describes a change; it alone does not identify a cause.') for kind,a,b,c,d in measures])
