 factors=[('ramp height','same ball and surface','stopping distance'),('ramp surface','same ball and height','stopping distance'),('paper type','same size and water drop','absorption time'),('cloth type','same size and wetness','drying time'),('water amount','same plant kind, soil and light','growth marks'),('light condition','same plant kind, soil and water','growth marks'),('paper folds','same paper and toy load','supported load'),('magnet distance','same magnet and clip','attraction result'),('cup cover','same cup and starting water','water level change'),('shade','same starting wet area and surface','wet area change'),('ball type','same ramp height and surface','travel distance'),('soil type','same plant kind, water and light','growth marks')]
