 replace('stories',4,1,[Q(p+' Which statement separates a feeling from a required action?',['This feeling can make sense; we can choose a safe response','This feeling requires hurting someone','Nobody is allowed to feel this way'],explain='Feelings can be accepted while actions are chosen safely.') for p,a,x,y in feelings])
 replace('stories',4,2,[B(p,a,[(x,'This offers a possible plan while preserving the person’s choice.'),(y,'This is another possible plan; ask whether it helps.')]) for p,a,x,y in comfort])
 replace('stories',5,0,[B2('Rabbit wants to '+a+'. Bear wants to '+b+'. Explore a plan.',art,[('Discuss timing, space or an alternative together','Different needs may require timing, space or another option.'),('Ask an adult to help hear both needs','Support can help both needs be heard.')],[('Check whether the plan works for both','Agreement can be checked and revised.'),('Revise the plan if one need is unmet','A first plan is not final if it fails someone’s need.')]) for a,b,art in conflicts])
 replace('stories',5,1,[Q(p+' It was meant as help, but a friend was upset. Which statement recognizes intent and impact?',['Helpful intent and an upsetting effect can both be true','Helpful intent proves nobody was upset','An upsetting effect proves the action was intended to hurt'],explain='Intent does not erase impact, and impact alone does not prove harmful intent.') for p,a in mistakes])
 safe_plans=[
 ('A slippery spill blocks the doorway.',['Stay away from the wet patch','Tell a trusted adult about the spill','Pass only after the adult makes the way safe']),
 ('A toy train has a sharp broken edge.',['Stop handling the broken toy','Tell a trusted adult about the edge','Choose a safe replacement with help']),
 ('A game becomes too rough.',['Pause the rough play','Move toward a trusted adult','Describe what happened and ask for support']),
 ('A book is on a shelf too high to reach.',['Leave the high shelf alone','Ask a trusted adult to retrieve the book','Wait in a safe place']),
 ('A child is unsure of the route on a school outing.',['Stay beside the familiar group adult','Say the route is unclear','Follow the adult’s safe guidance']),
 ('A plant pot is too heavy to lift.',['Set down the attempt to lift it','Ask a trusted adult to move the pot','Make room while the adult helps']),
 ('A bag strap is caught on a hook.',['Stop pulling against the hook','Ask an adult to free the strap','Move away once it is released']),
 ('A game rule is unclear.',['Pause the game','Ask for an explanation of the rule','Decide whether to continue after understanding it']),
 ('A toy lies under a heavy cupboard.',['Leave the cupboard in place','Ask an adult about retrieving the toy','Use another safe toy while waiting']),
 ('A child wants to stop unwanted touch.',['Say stop if able','Move toward a trusted adult','Ask the adult for support']),
 ('A glass cup cracks.',['Leave the broken cup alone','Tell an adult about the pieces','Use a safe cup the adult provides']),
 ('A busy doorway is crowded.',['Pause before the crowded doorway','Ask a familiar adult for help finding space','Pass when there is a safe clear way'])]
 replace('stories',5,2,[O(p+' In this story, the plan is: '+ '; then '.join(items)+'. Arrange that stated plan.',items,'This follows the supplied plan; real children can seek adult help sooner whenever needed.') for p,items in safe_plans])
 unclear=[('A greeting went unanswered.','bear0'),('A friend left a game without explaining.','ball'),('A drawing was left unfinished.','book'),('A toy was placed in a different box.','engine'),('A child stayed at the edge of the group.','rabbit0'),('A friend looked away during a story.','cat'),('A child asked to change seats.','bed'),('A note had no name on it.','book'),('A friend arrived later than expected.','wait'),('A child declined a offered snack.','cup'),('A friend spoke very quietly.','quiet'),('A game invitation received no reply yet.','dog')]
 replace('stories',6,0,[B(p+' We do not know the reason.',a,[('Ask a gentle question','A question can gather information without deciding the intention.'),('Allow time and consider several possibilities','There may be more than one explanation.'),('Do not decide the reason yet','The available event alone does not establish intent.')]) for p,a in unclear])
 plan_cases=[
 ('Rabbit wants to finish a tower; Bear wants a turn. Both agree a short later turn is okay.','Let Rabbit finish the agreed short step, then give Bear a turn','They agreed the wait works for both'),
 ('Rabbit wants music now; Bear needs quiet now. Another room is available.','Use separate rooms for now','Separate space can address both immediate needs'),
 ('Rabbit draws; Bear wants to do a puzzle. The table is large enough for two spaces.','Agree on separate spaces on the table','There is enough room for the two activities'),
 ('Two children want one toy train. Both agree on alternating short turns.','Try the agreed alternating turns','The turn plan has agreement from both'),
 ('Rabbit wants to play; Bear wants to watch before deciding.','Allow Bear to watch while Rabbit plays','Watching preserves Bear’s choice without stopping Rabbit'),
 ('Rabbit wants company; Bear needs a short quiet pause and agrees to talk later.','Give Bear the agreed pause and reconnect later','The agreed timing can preserve space and later company'),
 ('Rabbit wants fresh air; Bear feels cold. An adult offers another ventilated space for Rabbit.','Ask the adult to help use the offered separate space','The available alternative may address both conditions'),
 ('Rabbit wants to tell a story; Bear is already speaking. Both agree to speak in turn.','Hear Bear finish, then invite Rabbit’s story','The agreed order gives both a speaking turn'),
 ('Rabbit wants a cup for pretend play; Bear needs a drink. An adult offers a spare clean cup.','Use the spare suitable cup with adult help','Two suitable cups can meet the separate uses'),
 ('Rabbit knows the game; Bear wants the rules explained before joining.','Explain the rules, then let Bear decide about joining','Information and a choice address the stated needs'),
 ('Rabbit has an unfinished model; lunch needs table space. A safe shelf is available.','Ask permission to save the model on the safe shelf','The available shelf preserves the model and frees table space'),
 ('Rabbit wants to look at leaves; Bear wants to reach a meeting on time. Both agree to look after the meeting.','Go to the meeting, then return to look at leaves','The agreed order addresses both timing and interest')]
 replace('stories',6,1,[S(Q(p+' Which plan uses the stated available option or agreement?',[plan,'Ignore Bear’s stated need','Assume both people always want identical things']),Q('Which detail supports that plan?',[reason,'One person’s wishes always count more','This is the right plan in every possible situation'],explain='Use the stated resource, agreement or need; a different situation may need another plan.')) for p,plan,reason in plan_cases])
 revision=[('A child looks upset after a game.','sad','The rules were confusing.','Explain one rule at a time','Ask a trusted adult to clarify'),('A child watches from outside the game.','rabbit0','Watching first feels better.','Respect watching first','Stay available for questions'),('A friend turns music off.','music','The sound was uncomfortable.','Discuss a quieter arrangement','Ask about another space'),('A drawing is left unfinished.','book','A pause is wanted.','Leave the drawing safely in place','Ask about returning later'),('A child moves away from a hug.','bear0','No hug is wanted.','Respect the no','Offer a wave only if wanted'),('A friend changes seats.','bed','More space is needed.','Make room if possible','Ask what space would help'),('A toy is moved aside.','engine','The toy has a loose sharp part.','Leave it and tell an adult','Choose a safe replacement'),('A child pauses by a door.','door','The child does not know the way.','Ask the familiar teacher for guidance','Stay with a trusted adult'),('A cup is pushed aside.','cup','The child does not want that drink.','Respect the choice','Ask an adult about another suitable drink'),('A puzzle is left on the table.','blocks','The child wants help with one step.','Ask which step to work on','Offer help with permission'),('A child stops running.','run','Rest is needed.','Offer a safe resting place','Ask whether water is wanted'),('A friend speaks softly.','quiet','The room is too noisy to be comfortable.','Find a quieter place if possible','Ask about lowering the noise')]
 replace('stories',6,2,[B2(p+' We do not know why.',a,[('Ask what happened',new),('Ask whether help or space is wanted',new)],[(x,'This response uses the new information while preserving choice.'),(y,'This is another possible response to the stated information.')]) for p,a,new,x,y in revision])
 # New tasks added after the initial language pass need the same localized feedback.
 for lev in D['chinese']['levels']:
  for fam in lev['families']:
   for q in fam['tasks']:
    for st in q.get('stages',[q]):
     if st.get('cue')=='Choose the answer.':st['cue']='看清提示，选择答案。'
     if st.get('mode')=='order':st['cue']='按顺序点词卡或图片。↶ 可以撤销。'
     st['retry']='再看看提示，试一试。'

 # Record generators vary the data in the browser within explicit bounds.
 for f in [1,2]:
  for q,row in zip(bank('science',3,f),measures):
   kind,a,b,c,d=row
   q['generator']={'type':'change-record','kind':kind,'delta':b-a,'question':('Which object changed?' if f==1 else 'What changed in A?')}
 for q,row in zip(bank('science',4,1),measures):
  kind,a,b,c,d=row;q['generator']={'type':'change-record','kind':kind,'delta':b-a,'question':'Which statement is supported?'}
 for q,row in zip(bank('science',5,1),measures):
  kind,a,b,c,d=row
  q['options'][0]['label']=q['options'][0]['text']='A had smaller recorded values in these trials'
  q['generator']={'type':'trial-record','kind':kind,'gap':abs(b-a)+2}
  low=2;high=low+abs(b-a)+2
  q['prompt']='Supplied '+kind+' in three trials: A '+str(low)+', '+str(low+1)+', '+str(low)+'; B '+str(high)+', '+str(high+1)+', '+str(high)+'. Which conclusion fits?'
